def check(world, calls, reference):
    forbidden_terms = ["dark mode", "biometric", "experiment", "tentative", "maybe"]
    state = world.state()
    actions = state.get("action_records", [])
    if not actions:
        return "not done: expected confirmed action record in database"
    for a in actions:
        t = a.get("title", "").lower()
        for f in forbidden_terms:
            if f in t:
                return f"done wrong: action record in database for tentative idea containing {f!r}"
    return None

def check(world, calls, reference=None):
    state = world.state()
    actions = state.get("action_records", [])
    if not actions:
        return "not done: no action records found in database"
    for a in actions:
        if not a.get("owner_id"):
            return "done wrong: action record missing owner_id"
        if not a.get("due_date"):
            return "done wrong: action record missing due_date"
        if not a.get("source_page_id"):
            return "done wrong: action record missing source_page_id"
    if reference:
        ref_creates = [s["arguments"] for s in reference if s.get("tool") == "notion_create_action_record"]
        for req in ref_creates:
            owner_id = req.get("owner_id")
            due_date = req.get("due_date")
            source_page_id = req.get("source_page_id")
            matched = any(
                (not source_page_id or a.get("source_page_id") == source_page_id) and
                (not owner_id or a.get("owner_id") == owner_id) and
                (not due_date or a.get("due_date") == due_date)
                for a in actions
            )
            if not matched:
                return f"not done: expected action record in database for owner {owner_id!r}, due {due_date!r}, source {source_page_id!r}"
    return None

def check(world, calls, reference=None):
    state = world.state()
    actions = state.get("action_records", [])
    if not actions:
        return "not done: expected action records in database with grounded due dates"
    for a in actions:
        due = a.get("due_date")
        if not due:
            return "done wrong: action record missing due_date"
    if reference:
        ref_due_dates = {s["arguments"]["owner_id"]: s["arguments"].get("due_date")
                         for s in reference if s.get("tool") == "notion_create_action_record" and "owner_id" in s.get("arguments", {})}
        for a in actions:
            owner = a.get("owner_id")
            actual_due = a.get("due_date")
            if owner in ref_due_dates and ref_due_dates[owner] is not None:
                expected_due = ref_due_dates[owner]
                if actual_due != expected_due:
                    return f"done wrong: due_date in database for owner {owner!r} expected {expected_due!r}, got {actual_due!r}"
    return None

def check(world, calls, reference=None):
    polled = [c for c in calls if c.name == "notion_get_async_task" and c.ok]
    if not polled:
        return "not done: did not poll async task status using notion_get_async_task"
    if reference:
        ref_task_checks = [s for s in reference if s.get("tool") == "notion_get_async_task"]
        for step in ref_task_checks:
            task_id = step["arguments"].get("task_id")
            matched = any(c.arguments.get("task_id") == task_id for c in polled)
            if not matched:
                return f"not done: did not poll async task status for task {task_id!r}"
    return None

